/** Lints this project, with its imports and exports organized. */
export default {
    ignore: [
        ".cache",
        ".git",
        ".yarn",
        "coverage",
        // generated by project.sh, and ignored by git
        "docker-compose.yml",
        "node_modules",
        "packages/*/bin",
        "shared/*/bin",
        "yarn.lock",
        "*.tsbuildinfo",
    ],
    rules: {
        preset: "recommended",
        suspicious: {
            noTemplateCurlyInString: "off",
        },
        assist: {
            enabled: true,
            actions: { source: { organizeImports: "on" } },
        },
    },
};
